menu = {'cay': 15, 'kahve': 35, 'tost': 50}

- menu.keys()   -> ['cay', 'kahve', 'tost']
- menu.values() -> [15, 35, 50]
- menu.items()  -> [('cay', 15), ('kahve', 35), ...]

for urun, fiyat in menu.items():
    print(f'{urun.upper()}: {fiyat} TL')

