calma_listesi = []

while True:
    sarki = input('Eklenecek şarkı (Çıkış için q): ')
    if sarki.lower() == 'q':
        break
    calma_listesi.append(sarki.title())

print('\n🎵 Çalma Listeniz:')
for sira, s in enumerate(calma_listesi, 1):
    print(f'{sira}. {s}')

notlar = [70, 85, 40, 95, 60, 100, 55]

gecenler = []
kalanlar = []

for n in notlar:
    if n >= 50:
        gecenler.append(n)
    else:
        kalanlar.append(n)

print(f'Geçen Sayısı: {len(gecenler)} | Kalan Sayısı: {len(kalanlar)}')

